function divisionClubs(name,division){let l=leagues.find(x=>x.name===name)||leagues[0];return (division==='D2'?l.clubsD2:division==='D3'?l.clubsD3:l.clubs).slice()}
function clubCrestHtml(name){let s=clubStyles[name]||{short:initials(name),c1:'#314c68',c2:'#ffffff'};return `<span class="club-crest" style="--crest-a:${s.c1};--crest-b:${s.c2}">${esc(s.short)}</span>`}
function migrateClubNames(s){let map={};Object.keys(OLD_CLUBS).forEach(league=>{let l=leagues.find(x=>x.name===league),real=l?l.clubs:[];OLD_CLUBS[league].forEach((old,i)=>{map[old]=real[i%real.length]})});let rename=v=>v===s.club?.name?v:(map[v]||v);['calendar','history'].forEach(k=>{(s[k]||[]).forEach(m=>{if(!m||typeof m!=='object')return;if('home' in m)m.home=rename(m.home);if('away' in m)m.away=rename(m.away);if('opponent' in m)m.opponent=rename(m.opponent)})});(s.offers||[]).forEach(o=>{o.club=rename(o.club)});(s.transferHistory||[]).forEach(t=>{if(t.text)Object.keys(map).forEach(old=>{t.text=t.text.split(old).join(map[old])})});return s}
const divs={D1:{label:'Primera división',range:[88,95]},D2:{label:'Segunda división',range:[82,87]},D3:{label:'Tercera división',range:[76,81]},D4:{label:'Cuarta división',range:[70,75]},ACADEMIA:{label:'Academia',range:[62,69]}};
let playerDB={};let state=null;let audioCtx=null,musicOn=false,musicMuted=false,musicPlaying=false,musicVolume=.32,soundOn=true,matchTimer=null,songList=[],songIndex=0,songUrls=[];
playerDB=window.CHICAGO_PLAYERS||{D1:[],D2:[],D3:[],D4:[],ACADEMIA:[]};document.addEventListener('contextmenu',e=>e.preventDefault());document.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(e.key==='F12'||(e.ctrlKey&&e.shiftKey&&['i','j','c'].includes(k))||(e.ctrlKey&&['u','s'].includes(k))){e.preventDefault();e.stopPropagation()}},true);
function init(){try{const saved=localStorage.getItem('chicago_manager_save');if(saved){try{state=JSON.parse(saved);if(!isUsableSave(state)){localStorage.removeItem('chicago_manager_save');state=null}}catch(e){state=null;try{localStorage.removeItem('chicago_manager_save')}catch(_){}}}if(!state){showSetup()}else{state=migrateClubNames(normalizeState(state));try{persist()}catch(e){}showApp();renderPage()}}catch(e){console.error('CHICAGO: no se pudo iniciar la partida',e);try{localStorage.removeItem('chicago_manager_save')}catch(_){}state=null;showSetup();toast('Se descartó una partida incompatible. Comienza una nueva carrera.',true)}}
function isUsableSave(s){return !!(s&&s.version&&s.version>=2&&s.club&&Array.isArray(s.squad)&&Array.isArray(s.calendar))}
function normalizeState(s){const defaults={name:'Chicago Arena',capacity:1200,north:1,south:1,east:1,west:1,color:'#263b55',homeKit:'#a91f36',awayKit:'#f0f0f0'};s.version=2;s.club=s.club||{};s.club.name=s.club.name||'Mi club';s.club.coach=s.club.coach||'Entrenador';s.club.league=s.club.league||leagues[0].name;s.club.flag=s.club.flag||leagues[0].flag;if(!divs[s.club.division])s.club.division='D2';s.stadium={...defaults,...(s.stadium||{})};s.date=/^\d{4}-\d{2}-\d{2}$/.test(s.date||'')?s.date:'2027-01-01';s.season=Number.isFinite(s.season)?s.season:1;s.balance=Number.isFinite(s.balance)?s.balance:1000000;s.morale=Number.isFinite(s.morale)?s.morale:75;['inbox','news','offers','history','calendar','trainingUsed','marketDailyIds','marketSeenIds','achievements','investments'].forEach(k=>{if(!Array.isArray(s[k]))s[k]=[]});s.calendar=s.calendar.filter(m=>m.competition!=='Copa Chicago');s.stats={played:0,wins:0,draws:0,losses:0,goals:0,conceded:0,...(s.stats||{})};s.tacticXI=s.tacticXI||{};s.trainingWeek=s.trainingWeek||weekKey(s.date);s.captainId=s.captainId||s.squad[0]?.uid||'';if(!Array.isArray(s.marketPool))s.marketPool=makeMarketPool();if(!s.cup||s.cup.season!==s.season||s.cup.league!==s.club.league||!s.cup.totalRounds||!Array.isArray(s.cup.rounds)||!s.cup.rounds.length)generateCup(s,Number(s.date.slice(0,4))+(s.date.endsWith('-12-31')?1:0));return s}
function persist(){localStorage.setItem('chicago_manager_save',JSON.stringify(state))}
function showSetup(){$('#onboarding').classList.remove('hidden');$('#app').classList.add('hidden');renderLeagueChoices();renderCaptains()}
function renderLeagueChoices(){$('#leagueChoices').innerHTML=leagues.map((l,i)=>`<button class="league-choice ${i===0?'selected':''}" data-league="${i}"><span class="league-flag">${l.flag}</span><span><b>${l.name}</b><small>Dificultad ${l.difficulty} · Inicio ${l.start}</small></span></button>`).join('');$$('.league-choice').forEach(b=>b.onclick=()=>{$$('.league-choice').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');selectedLeague=+b.dataset.league})}
let selectedLeague=0,selectedCaptain=null,uploadedLogo='';
function renderCaptains(){let p=playerDB.D1||[];$('#captainChoices').innerHTML=p.map(x=>`<button class="captain-choice" data-captain="${esc(x.id)}"><span class="player-avatar">${esc(x.nombre.slice(0,1).toUpperCase())}</span><b>${esc(x.nombre)}</b><small>${x.media} · ${x.posicion}</small></button>`).join('');$$('.captain-choice').forEach(b=>b.onclick=()=>{$$('.captain-choice').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');selectedCaptain=b.dataset.captain})}
