$('#stepLeague').onclick=()=>setupStep(2);
$('#logoFile').onchange=e=>{let f=e.target.files[0];if(!f)return;if(f.size>1200000){toast('El escudo debe pesar menos de 1.2 MB',true);return}let r=new FileReader();r.onload=()=>{uploadedLogo=r.result;$('#logoPreview').innerHTML=`<img src="${uploadedLogo}">`};r.readAsDataURL(f)};
$('#stepClub').onclick=()=>{if(!$('#clubName').value.trim()||!$('#coachName').value.trim()){toast('Completa el nombre del club y entrenador',true);return}setupStep(3)};
$('#startCareer').onclick=()=>{if(!selectedCaptain){toast('Debes elegir un capitán de D1',true);return}let league=leagues[selectedLeague],start=league.start;let captain=(playerDB.D1||[]).find(p=>p.id===selectedCaptain);let source=[...(playerDB.D4||[]),...(playerDB.ACADEMIA||[]),...(playerDB.D3||[])].filter(p=>p.media<=78);let used=new Set([captain.id]),usedNames=new Set([captain.nombre.toLowerCase()]);let squad=[moderatePlayer(clonePlayer(captain,'club'),82)];let needed=['GK','AM','DM','FWD'].filter(pos=>pos!==captain.posicion),extras=['GK','AM','DM','FWD'].sort(()=>Math.random()-.5).slice(0,2);[...needed,...extras].sort(()=>Math.random()-.5).forEach(pos=>{let options=source.filter(x=>x.posicion===pos&&!used.has(x.id)&&!usedNames.has(x.nombre.toLowerCase()));if(!options.length)options=source.filter(x=>!used.has(x.id)&&!usedNames.has(x.nombre.toLowerCase()));if(!options.length)return;let p=options[Math.floor(Math.random()*options.length)];used.add(p.id);usedNames.add(p.nombre.toLowerCase());let q=clonePlayer(p,'club');q.valor=playerValue(q.media);q.salario=Math.round(q.media*450);squad.push(q)});squad.forEach(p=>p.contract=2);if(squad.length!==6||new Set(squad.map(p=>p.nombre.toLowerCase())).size!==6){toast('No se pudo formar un equipo inicial válido de seis jugadores.',true);return}
state={version:2,club:{name:$('#clubName').value.trim(),coach:$('#coachName').value.trim(),logo:uploadedLogo,league:league.name,flag:league.flag,division:start,rep:40},date:'2027-01-01',season:1,week:1,balance:Math.round(1000000+Math.random()*4000000),stadium:{name:'Chicago Arena',capacity:1200,north:1,south:1,east:1,west:1,color:'#263b55',homeKit:'#a91f36',awayKit:'#f0f0f0'},inbox:[],news:[{type:'club',title:'Nuevo proyecto deportivo',body:`${$('#coachName').value.trim()} asumió como entrenador de ${$('#clubName').value.trim()}.`,date:'2027-01-01'},{type:'club',title:'Objetivo: construir desde abajo',body:'La directiva espera crecimiento, estabilidad económica y una lucha por el ascenso.',date:'2027-01-01'}],squad,captainId:squad.find(p=>p.id===captain.id)?.uid||squad[0].uid,marketOpen:true,trainingWeek:'2027-W01',trainingUsed:[],trainingSessions:{},offers:[],history:[],tactic:'Equilibrada',formation:'1-1-1',morale:75,stamina:100,calendar:[],lastPlayed:null,competition:'Liga',music:false,sound:true,stats:{played:0,wins:0,draws:0,losses:0,goals:0,conceded:0},marketPool:makeMarketPool(),marketViewedDate:null,marketDailyIds:[],marketSeenIds:[],achievements:[],investments:[]};generateCalendar();generateCup();state.inbox=[{id:'welcome',from:'Directiva',subject:'Bienvenido al club',body:'El club inicia un nuevo proyecto con un presupuesto limitado. Construye una plantilla competitiva y cuida las finanzas.',date:state.date,read:false}];persist();showApp();renderPage();toast('¡Tu carrera ha comenzado!')};
function playerValue(media){return Math.round(200000000*Math.pow(Math.max(35,media)/90,7))}function moderatePlayer(p,maxMedia){let media=Math.min(p.media,maxMedia);if(media<p.media){let f=media/p.media;Object.keys(p.atributos||{}).forEach(k=>p.atributos[k]=Math.round(p.atributos[k]*f));p.media=media;p.valor=playerValue(media);p.salario=Math.round(media*450)}return p}function initials(name){let w=String(name||'PL').replace(/[^\p{L}\p{N} ]/gu,' ').trim().split(/\s+/).filter(Boolean);return w.length>1?(w[0][0]+w[1][0]).toUpperCase():String(w[0]||'PL').slice(0,2).toUpperCase()}function clonePlayer(p,source){return {...JSON.parse(JSON.stringify(p)),valor:playerValue(p.media),salario:Math.round(p.media*850),uid:p.id+'-'+Math.random().toString(36).slice(2,7),source,trained:0,form:0,fitness:100,morale:75,contract:2}}
function makeMarketPool(){let all=[];Object.entries(playerDB).forEach(([division,a])=>a.forEach(p=>{let q=clonePlayer(p,'market');q.division=division;q.transferListed=Math.random()<.48;all.push(q)}));all.sort(()=>Math.random()-.5);all.slice(0,Math.min(12,all.length)).forEach(p=>p.transferListed=true);return all}
function squadAverage(){return (state.squad||[]).reduce((a,p)=>a+(p.media||0),0)/Math.max(1,(state.squad||[]).length)}
function marketEligible(){let names=new Set((state.squad||[]).map(p=>p.nombre.toLowerCase())),avg=squadAverage(),base=(state.marketPool||[]).filter(p=>p.transferListed&&!p.sold&&!names.has(p.nombre.toLowerCase()));let balanced=base.filter(p=>p.media<=avg+6).sort((a,b)=>Math.abs(a.media-(avg+2))-Math.abs(b.media-(avg+2))||a.valor-b.valor);return balanced.length>=3?balanced:base.sort((a,b)=>Math.abs(a.media-(avg+2))-Math.abs(b.media-(avg+2))||a.valor-b.valor)}
function ensureMarketDay(){if(!state.marketPool)return;let eligible=marketEligible();state.marketSeenIds=state.marketSeenIds||[];if(state.marketViewedDate!==state.date){let fresh=eligible.filter(p=>!state.marketSeenIds.includes(p.uid));if(fresh.length<3){state.marketSeenIds=[];fresh=eligible}state.marketViewedDate=state.date;state.marketDailyIds=fresh.slice(0,3).map(p=>p.uid);state.marketSeenIds.push(...state.marketDailyIds);persist()}if(!state.marketDailyIds)state.marketDailyIds=eligible.slice(0,3).map(p=>p.uid)}
function marketDailyPool(){ensureMarketDay();return (state.marketDailyIds||[]).map(id=>state.marketPool.find(p=>p.uid===id)).filter(p=>p&&!p.sold&&!state.squad.some(s=>s.nombre.toLowerCase()===p.nombre.toLowerCase()))}
function marketGridHtml(){let q=($('#marketSearch')?.value||'').toLowerCase(),d=$('#marketDiv')?.value||'',pos=$('#marketPos')?.value||'',sort=$('#marketSort')?.value||'rating',available=new Set(state.marketDailyIds||[]),names=new Set((state.squad||[]).map(p=>p.nombre.toLowerCase())),untouched=!q&&!d&&!pos&&sort==='rating';let pool=untouched?marketDailyPool():(state.marketPool||[]).filter(p=>!p.sold&&!names.has(p.nombre.toLowerCase())&&p.nombre.toLowerCase().includes(q)&&(!d||p.division===d)&&(!pos||p.posicion===pos));pool=pool.slice().sort((a,b)=>sort==='value'?a.valor-b.valor:b.media-a.media);return pool.map(p=>marketCard(p,available.has(p.uid))).join('')||'<div class="empty-state">No hay jugadores que coincidan con la búsqueda.</div>'}
function marketRecommendations(){let avg=squadAverage(),names=new Set((state.squad||[]).map(p=>p.nombre.toLowerCase())),available=new Set(state.marketDailyIds||[]);let rec=(state.marketPool||[]).filter(p=>p.transferListed&&!p.sold&&!names.has(p.nombre.toLowerCase())&&p.media<=avg+6&&p.media>=avg-14).sort((a,b)=>Math.abs(a.media-(avg+2))-Math.abs(b.media-(avg+2))||a.valor-b.valor).slice(0,3);if(!rec.length)rec=marketDailyPool().slice(0,3);return `<div class="panel"><div class="panel-head"><div><div class="panel-title">Recomendados para tu plantilla</div><div class="panel-sub">Media actual ${avg.toFixed(1)} · buscamos perfiles que encajen con tu equipo</div></div><span class="badge green">IA</span></div><div class="player-grid">${rec.map(p=>marketCard(p,available.has(p.uid))).join('')}</div></div>`}
function generateCalendar(){let year=Number(state.date.slice(0,4))+(state.date.endsWith('-12-31')?1:0),clubs=divisionClubs(state.club.league,state.club.division),club=state.club.name;clubs[0]=club;let n=clubs.length,firstLeg=[],rotation=clubs.slice();for(let r=0;r<n-1;r++){let round=[];for(let i=0;i<n/2;i++){let home=rotation[i],away=rotation[n-1-i];if((r+i)%2)[home,away]=[away,home];round.push({home,away,date:addDays(`${year}-01-08`,r*18),competition:'Liga',season:state.season,played:false,score:null})}firstLeg.push(...round);state.calendar.push(...round);rotation=[rotation[0],rotation[n-1],...rotation.slice(1,n-1).reverse()]}firstLeg.forEach((m,i)=>state.calendar.push({home:m.away,away:m.home,date:addDays(`${year}-07-10`,Math.floor(i/(n/2))*18),competition:'Liga',season:state.season,played:false,score:null}));state.calendar.sort((a,b)=>a.date.localeCompare(b.date))}
const CUP_NAMES={'Colombia BetPlay':'Copa Colombia','Argentina':'Copa Argentina','Brasil':'Copa do Brasil','México':'Copa MX','España':'Copa del Rey','Portugal':'Taça de Portugal','Inglaterra':'FA Cup','Italia':'Coppa Italia','Rusia':'Copa de Rusia','MLS':'U.S. Open Cup'};
function cupNameFor(s){return CUP_NAMES[s.club.league]||'Copa '+s.club.league}
function cupTeamsFor(s){let d1=divisionClubs(s.club.league,'D1'),teams=[...d1,...divisionClubs(s.club.league,'D2'),...divisionClubs(s.club.league,'D3')],i=teams.indexOf(d1[0]);if(i>=0)teams[i]=s.club.name;else teams.unshift(s.club.name);return [...new Set(teams)]}
function cupRoundName(i){return ['Ronda preliminar','Octavos de final','Cuartos de final','Semifinal','Final'][i]||('Ronda '+(i+1))}
function cupDateFor(s,i,year){return addDays(`${year}-01-15`,i*21)}
function addCupRoundToCalendar(s,i){let round=s.cup?.rounds?.[i];if(!round||s.cup.eliminated)return;round.matches.forEach(m=>{if(!s.calendar.some(x=>x.cup&&x.cupRound===i&&x.season===s.season&&x.home===m.home&&x.away===m.away))s.calendar.push({home:m.home,away:m.away,date:m.date,competition:s.cup.name,season:s.season,round:round.name,cup:true,cupRound:i,played:false,score:null})});s.calendar.sort((a,b)=>a.date.localeCompare(b.date))}
function generateCup(s=state,year=Number(s.date.slice(0,4))+(s.date.endsWith('-12-31')?1:0)){let name=cupNameFor(s),teams=cupTeamsFor(s).sort(()=>Math.random()-.5);let totalRounds=Math.ceil(Math.log2(Math.max(2,teams.length)));s.cup={season:s.season,league:s.club.league,name,year,totalRounds,rounds:[],roundIndex:0,champion:null,eliminated:false};let size=2**totalRounds,byes=size-teams.length,playing=teams.slice(0,teams.length-byes),byeTeams=teams.slice(teams.length-byes),matches=[];for(let i=0;i<playing.length;i+=2)matches.push({home:playing[i],away:playing[i+1],date:cupDateFor(s,0,year),played:false,score:null});s.cup.rounds.push({name:cupRoundName(0),matches,byes:byeTeams});addCupRoundToCalendar(s,0);return s.cup}
function processCupDay(s=state){let c=s.cup;if(!c||c.season!==s.season||!c.rounds?.length)return;let i=c.roundIndex||0,r=c.rounds[i];if(!r)return;r.matches.forEach(m=>{if(m.date<=s.date&&!m.played&&m.home!==s.club.name&&m.away!==s.club.name){let h=1+Math.floor(Math.random()*4),a=Math.floor(Math.random()*4);if(h===a)h++;m.played=true;m.score={home:h,away:a};let cal=s.calendar.find(x=>x.cup&&x.cupRound===i&&x.season===s.season&&x.home===m.home&&x.away===m.away);if(cal){cal.played=true;cal.score={...m.score}}}});let own=r.matches.find(m=>m.home===s.club.name||m.away===s.club.name);if(own&&!own.played)return;if(!r.matches.every(m=>m.played))return;let winners=r.matches.map(m=>m.score.home>m.score.away?m.home:m.away).concat(r.byes||[]);if(own&&!winners.includes(s.club.name)&&!c.eliminated){c.eliminated=true;s.news.unshift({type:'league',title:'Eliminados de '+c.name,body:`${s.club.name} cayó en ${r.name} y deja la copa.`,date:s.date})}if(i===(c.totalRounds||c.rounds.length)-1){c.champion=winners[0];s.news.unshift({type:'league',title:'Campeón de '+c.name,body:`${c.champion} ganó la copa de esta temporada.`,date:s.date});return}let next=[];for(let j=0;j<winners.length;j+=2)next.push({home:winners[j],away:winners[j+1],date:addDays(s.date,21),played:false,score:null});c.rounds.push({name:cupRoundName(i+1),matches:next,byes:[]});c.roundIndex=i+1;addCupRoundToCalendar(s,i+1)}
function syncCupResult(s,m,homeScore,awayScore){let c=s.cup;if(!c||!m.cup)return;let cm=c.rounds[m.cupRound]?.matches?.find(x=>x.home===m.home&&x.away===m.away);if(cm){cm.played=true;cm.score={home:homeScore,away:awayScore}}let won=m.home===s.club.name?homeScore>awayScore:awayScore>homeScore;s.news.unshift({type:'league',title:won?'Avanzamos en '+c.name:'Eliminados de '+c.name,body:won?`Victoria ante ${m.home===s.club.name?m.away:m.home}. El equipo sigue en la copa.`:`Derrota ante ${m.home===s.club.name?m.away:m.home}. El equipo queda fuera de la copa.`,date:s.date});processCupDay(s)}
function showApp(){$('#onboarding').classList.add('hidden');$('#app').classList.remove('hidden');$('#sideClub').textContent=state.club.name;$('#sideDivision').textContent=divs[state.club.division].label;setLogo($('#sideLogo'),state.club.logo,state.club.name);$('#profileCoach').textContent=state.club.coach;$('#profileAvatar').textContent=state.club.coach.slice(0,1).toUpperCase();updateTop()}
