const pages={home:'Inicio',squad:'Plantilla',calendar:'Calendario',tactics:'Tácticas',market:'Mercado de fichajes',training:'Entrenamiento',competitions:'Competiciones',inbox:'Bandeja de entrada',finances:'Finanzas',stadium:'Estadio',settings:'Configuración',profile:'Perfil'};
