function resolveOffer(id,accept){let o=state.offers.find(x=>x.id===id);if(!o)return;state.offers=state.offers.filter(x=>x.id!==id);if(accept){let p=state.squad.find(x=>x.uid===o.playerId);if(p){state.squad=state.squad.filter(x=>x.uid!==p.uid);state.balance+=o.amount;state.transferHistory=state.transferHistory||[];state.transferHistory.push({text:'Venta a '+o.club+': '+p.nombre,amount:o.amount,type:'sale',date:state.date})}toast('Oferta aceptada')}else toast('Oferta rechazada');persist();renderPage('inbox')}
function train(){let id=state.trainingSelected,type=$('#trainType').value;if(!id){toast('Selecciona un jugador',true);return}let p=state.squad.find(x=>x.uid===id);if(state.trainingUsed.includes(id)){toast('Este jugador ya entrenó esta semana',true);return}if(state.trainingUsed.length>=5){toast('Ya utilizaste las cinco sesiones semanales',true);return}if(state.balance<100){toast('No tienes fondos para pagar la sesión',true);return}if(state.balance<100){toast('No tienes fondos para pagar la sesión',true);return}state.trainingUsed.push(id);if(type==='fisico'){p.fitness=Math.min(100,p.fitness+12)}else{p.atributos[type]=Math.min(99,p.atributos[type]+1);p.trained=(p.trained||0)+1;p.media=p.media}state.balance-=100;persist();renderPage('training');toast('Sesión completada para '+p.nombre)}
function startMatch(m){if(!state.tacticXI||!['GK','AM','DM','FWD'].every(k=>state.tacticXI[k])){toast('Configura tus cuatro titulares antes del partido.',true);go('tactics');return}if(m.date>state.date){toast('El partido todavía no está disponible',true);return}let home=m.home===state.club.name,opponent=home?m.away:m.home;let own=['GK','DM','AM','FWD'].map(pos=>state.squad.find(p=>p.uid===state.tacticXI[pos]));let avg=own.reduce((a,p)=>a+p.media,0)/4;let oppRating=avg+(Math.random()*12-6)+(state.club.division==='D1'?3:state.club.division==='D4'?-3:0);let events=simulateEvents(avg,oppRating,state.tactic,home,own),gf=events.filter(e=>e.goal==='home').length,ga=events.filter(e=>e.goal==='away').length;if(!home)[gf,ga]=[ga,gf];let duration=+($('#simSpeed')?.value||2);let html=`<div class="match-layout"><div><div class="scoreboard"><div class="eyebrow">SIMULACIÓN EN DIRECTO · ${esc(m.competition.toUpperCase())}</div><div class="score-big"><span id="liveHome">0</span> - <span id="liveAway">0</span></div><div class="muted">${esc(m.home)} vs ${esc(m.away)}</div><div class="muted" id="matchClock">00:00</div></div><div id="matchPitch" class="pitch" style="min-height:440px"><div class="pitch-mark left"></div><div class="pitch-mark right"></div><div id="matchDots"></div><div id="matchBall" class="ball" style="left:50%;top:50%"></div></div></div><div class="panel"><div class="panel-title">Crónica del encuentro</div><div class="panel-sub">Futsal · 4 contra 4 · dos tiempos de 30 minutos</div><div id="matchLog" class="match-log" style="margin-top:12px"></div><div id="matchStatus" class="hint" style="margin-top:12px">Preparando el encuentro...</div><button id="skipMatch" class="small-btn" style="margin-top:12px;width:100%">Completar simulación</button></div></div>`;
openModal(`<h3>Partido: ${esc(state.club.name)} vs ${esc(opponent)}</h3><div id="matchMount">${html}</div>`);
runMatchAnimation(m,events,home,duration,own,avg,oppRating);
}
function simulateEvents(own,opp,tactic,teamAtHome=true,ownPlayers=[]){let quality=(own-opp)+(tactic==='Presión alta'?1.5:tactic==='Defensiva'?-2:tactic==='Posesión'?1:0)+(teamAtHome?1:-1),attack=Math.max(3,Math.min(7,Math.round(5+quality*.7))),defense=10-attack,arr=[],ambient=['Remate que pasa cerca del poste.','Gran intervención del portero.','Recuperación en mitad de cancha.','Pase filtrado que rompe líneas.','El equipo intenta construir desde atrás.','Buena circulación y cambio de orientación.'];for(let min=2;min<=60;min+=3){if(Math.random()+quality*.012>.58)arr.push({min,text:ambient[Math.floor(Math.random()*ambient.length)]})}let kinds=[...Array(attack).fill('attack'),...Array(defense).fill('defense')];for(let i=kinds.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[kinds[i],kinds[j]]=[kinds[j],kinds[i]]}let attacker=ownPlayers.find(p=>['FWD','AM'].includes(p.posicion))||ownPlayers[0]||null,defender=ownPlayers.find(p=>['GK','DM'].includes(p.posicion))||ownPlayers[1]||null,used=new Set();kinds.forEach((kind,i)=>{let min=4+Math.floor(i*5.2)+Math.floor(Math.random()*2);while(used.has(min)&&min<59)min++;used.add(min);arr.push({min,decision:true,kind,quality,player:kind==='attack'?attacker:defender,text:kind==='attack'?`${attacker?.nombre||'Tu equipo'} busca el pase al centro.`:`${defender?.nombre||'Tu defensa'} debe cerrar el contragolpe.`})});return arr.sort((a,b)=>a.min-b.min)}
function resolveMatchDecision(ev,choice){let p=ev.player||{},a=p.atributos||{},q=ev.quality||0,skill=p.media||70,r=Math.random();if(ev.kind==='attack'){let chance=choice==='pass'?.22+(a.pase||skill)*.0038+(a.control||skill)*.0012:choice==='dribble'?.18+(a.velocidad||skill)*.0044+(a.control||skill)*.0016:.16+(a.ataque||skill)*.0045;chance=Math.max(.12,Math.min(.78,chance+q*.012));let ok=r<chance;return{goal:ok,side:'own',text:ok?choice==='pass'?`${p.nombre||'Pase al centro'} encuentra al compañero y define`:choice==='dribble'?`${p.nombre||'Regate'} supera al marcador y remata`:`${p.nombre||'Remate'} la clavó al segundo palo`:choice==='pass'?'El pase al centro fue interceptado.':choice==='dribble'?'El regate se corta y se pierde la posesión.':'El remate se marcha desviado.'}}let chance=choice==='mark'?.42+(a.defensa||skill)*.0042:choice==='press'?.36+(a.defensa||skill)*.0038+(a.velocidad||skill)*.0014:.48+(a.defensa||skill)*.0034;chance=Math.max(.25,Math.min(.92,chance+q*.01));let ok=r<chance;return{goal:!ok,side:'rival',text:ok?choice==='mark'?'Marcaje ajustado: se corta el avance rival.':choice==='press'?'Presión alta: recuperación en campo contrario.':'Despeje seguro al costado.':choice==='mark'?'El rival supera el marcaje y define.':choice==='press'?'La presión llega tarde y el rival aprovecha.':'El despeje queda corto y el rival castiga.'}}
function runMatchAnimation(m,events,home,duration,ownPlayers=[]){let opponent=home?m.away:m.home;let log=$('#matchLog'),ball=$('#matchBall'),dots=$('#matchDots'),clock=$('#matchClock'),h=$('#liveHome'),a=$('#liveAway'),status=$('#matchStatus');let count=0,scoreH=0,scoreA=0,interval=duration===4?260:duration===1?720:460;let teamDots='';for(let i=0;i<4;i++){let homeName=home?initials(ownPlayers[i]?.nombre||'Rival'):['R1','R2','R3','R4'][i],awayName=home?['R1','R2','R3','R4'][i]:initials(ownPlayers[i]?.nombre||'Rival'),homeStyle=home?`background:${state.stadium.homeKit}`:'',awayStyle=home?'':`background:${state.stadium.awayKit}`;teamDots+=`<div class="pitch-dot home" style="${homeStyle};left:${[8,31,63,88][i]}%;top:${[48,24,72,48][i]}%">${homeName}</div><div class="pitch-dot away" style="${awayStyle};left:${[12,39,68,92][i]}%;top:${[26,75,25,52][i]}%">${awayName}</div>`}dots.innerHTML=teamDots;const addLog=(s,goal=false)=>{let el=document.createElement('div');el.className='log-line';el.innerHTML=`<b>${String(count).padStart(2,'0')}'</b> ${goal?'<strong>'+s+'</strong>':esc(s)}`;log.append(el);log.scrollTop=log.scrollHeight};addLog('El árbitro da inicio al encuentro.');let idx=0,clockMin=0,waitingDecision=false;const autoChoice=ev=>{let q=ev.quality||0;if(ev.kind==='attack')return q>1?'shoot':q<-1?'pass':'dribble';return q<-1?'mark':q>1?'press':'clear'};const applyDecision=(ev,choice,manual=true)=>{let res=resolveMatchDecision(ev,choice);if(res.goal){if(res.side==='own'){if(home)scoreH++;else scoreA++}else{if(home)scoreA++;else scoreH++}addLog(res.text,true);playSound('goal')}else addLog(res.text);h.textContent=scoreH;a.textContent=scoreA;let box=$('#matchDecision');if(box)box.remove();if(manual){waitingDecision=false;matchTimer=setInterval(tick,interval)}};const showDecision=(ev)=>{let box=$('#matchDecision');if(!box){box=document.createElement('div');box.id='matchDecision';box.className='decision-box';status.parentElement.insertBefore(box,status.nextSibling)}let opts=ev.kind==='attack'?[['pass','Pasar al centro'],['dribble','Regatear'],['shoot','Rematar']]:[['mark','Marcar'],['press','Presionar'],['clear','Despejar']];box.innerHTML=`<div class="decision-head"><b>${ev.kind==='attack'?'DECISIÓN DE ATAQUE':'DECISIÓN DEFENSIVA'}</b><span>${(ev.quality||0)>0?'Tienes superioridad':'Equipo inferior'}</span></div><p>${esc(ev.text)}</p><div class="decision-options">${opts.map(([k,label])=>`<button class="decision-btn" data-decision="${k}">${label}</button>`).join('')}</div>`;box.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>applyDecision(ev,b.dataset.decision))};let tick=()=>{if(waitingDecision)return;if(idx>=events.length){finish();return}let ev=events[idx++];if(count<30&&ev.min>30)addLog('Descanso. Los equipos regresan al vestuario.');count=ev.min;clock.textContent=String(count).padStart(2,'0')+':00';let phase=ev.goal?(ev.goal==='home'?0:1):Math.floor(Math.random()*4),x=[76,24,50,50][phase]+(Math.random()-.5)*18,y=18+Math.random()*64;ball.style.left=x+'%';ball.style.top=y+'%';[...dots.children].forEach((dot,i)=>{let role=Math.floor(i/2),isHome=i%2===0,bx=isHome?[8,31,63,88][role]:[92,69,37,12][role],by=[48,24,72,48][role],px=bx+(x-bx)*(role===0?.12:.34)+(Math.random()-.5)*5,py=by+(y-by)*(role===0?.16:.38)+(Math.random()-.5)*7;dot.style.left=Math.max(4,Math.min(94,px))+'%';dot.style.top=Math.max(8,Math.min(88,py))+'%'});if(ev.decision){waitingDecision=true;clearInterval(matchTimer);matchTimer=null;showDecision(ev);return}if(ev.goal==='home'){scoreH++;h.textContent=scoreH;addLog(ev.text,true);playSound('goal')}else if(ev.goal==='away'){scoreA++;a.textContent=scoreA;addLog(ev.text,true);playSound('goal')}else addLog(ev.text);if(idx>=events.length)setTimeout(finish,interval)};matchTimer=setInterval(tick,interval);$('#skipMatch').onclick=()=>{clearInterval(matchTimer);matchTimer=null;waitingDecision=false;let box=$('#matchDecision');if(box)box.remove();while(idx<events.length){let ev=events[idx++];if(count<30&&ev.min>30)addLog('Descanso. Los equipos regresan al vestuario.');count=ev.min;if(ev.decision)applyDecision(ev,autoChoice(ev),false);else{if(ev.goal==='home')scoreH++;if(ev.goal==='away')scoreA++;addLog(ev.text,!!ev.goal)}}h.textContent=scoreH;a.textContent=scoreA;finish()};function finish(){if(m.played)return;clearInterval(matchTimer);matchTimer=null;let homeScore=home?scoreH:scoreA,awayScore=home?scoreA:scoreH;if((m.cup||m.competition===state.cup?.name||m.round==='Eliminatoria'||m.round==='Partido único de clasificación')&&homeScore===awayScore){if(Math.random()>.5){if(home)scoreH++;else scoreA++}else{if(home)scoreA++;else scoreH++}homeScore=home?scoreH:scoreA;awayScore=home?scoreA:scoreH;h.textContent=scoreH;a.textContent=scoreA;addLog('Muerte súbita: el desempate define al clasificado.')}m.played=true;m.score={home:scoreH,away:scoreA};if(m.competition.startsWith('Playoff')){let won=homeScore>awayScore;if(won){let target=m.competition.includes('Europa')?'Europa League':'Copa Sudamericana',opponents=target==='Europa League'?['Manchester City','Roma','Porto']:['Rosario Central','Pumas UNAM','Santos'];state.internationalQualification={competition:target,position:state.internationalQualification?.position||0,season:state.season};opponents.forEach((name,i)=>state.calendar.push({home:i%2?name:state.club.name,away:i%2?state.club.name:name,date:[`${Number(m.date.slice(0,4))}-02-01`,`${Number(m.date.slice(0,4))}-02-18`,`${Number(m.date.slice(0,4))}-03-05`][i],competition:target,season:m.season,round:'Fase de grupos',played:false,score:null}));state.news.unshift({type:'league',title:`Clasificados a ${target}`,body:`${state.club.name} ganó el playoff y avanzó a ${target}.`,date:state.date})}else{state.internationalQualification={competition:'Sin clasificación internacional',position:state.internationalQualification?.position||0,season:state.season};state.news.unshift({type:'league',title:'Eliminados del playoff internacional',body:`${state.club.name} no logró superar la eliminatoria.`,date:state.date})}}if(m.cup)syncCupResult(state,m,homeScore,awayScore);state.stats.played++;state.stats.goals+=homeScore;state.stats.conceded+=awayScore;if(homeScore>awayScore)state.stats.wins++;else if(homeScore===awayScore)state.stats.draws++;else state.stats.losses++;let matchIncome=home?Math.round(state.stadium.capacity*.72*(65+Math.random()*35)):Math.round(state.stadium.capacity*.12*35);state.balance+=matchIncome;state.morale=Math.max(40,Math.min(100,state.morale+(homeScore>awayScore?5:homeScore===awayScore?1:-4)));state.squad.forEach(p=>p.fitness=Math.max(50,(p.fitness||100)-Math.round(10+Math.random()*8)));state.history.push({date:m.date,opponent:home?m.away:m.home,gf:homeScore,ga:awayScore,competition:m.competition});if(state.history.slice(-3).length===3&&state.history.slice(-3).every(x=>x.gf<x.ga)){state.inbox=state.inbox||[];state.inbox.push({id:'board-warning-'+m.date,from:'Directiva',subject:'Preocupación por la racha de resultados',body:'El equipo acumula tres derrotas consecutivas. La junta solicita revisar la táctica y el rendimiento del cuerpo técnico.',date:m.date,read:false})}state.inbox=state.inbox||[];state.inbox.push({id:'match-'+m.date,from:'Directiva',subject:homeScore>awayScore?'Felicitaciones por el resultado':'Informe posterior al encuentro',body:homeScore>awayScore?'La directiva reconoce el esfuerzo del equipo. Esperamos mantener este nivel competitivo.':'Esperamos una reacción en el próximo encuentro. Revisa el planteamiento táctico y la preparación física.',date:m.date,read:false});state.lastPlayed=m.date;state.squad.forEach(p=>{if(p.contract>0)p.contract=Math.max(0,p.contract)});persist();status.innerHTML=`<b style="color:#6ee1ad">FINALIZADO</b> · ${scoreH}-${scoreA} · Ingresos ${money(matchIncome)}`;addLog('Final del partido. Resultado registrado.');$('#skipMatch').disabled=false;$('#skipMatch').textContent='Cerrar partido';$('#skipMatch').onclick=()=>closeModal();updateTop();playSound('whistle');}
}
function loadSong(){let a=$('#songPlayer');if(!a||!songList.length)return;a.src='songs/'+encodeURIComponent(songList[songIndex].path);a.volume=musicVolume;$('#songStatus')&&($('#songStatus').textContent=(songIndex+1)+' / '+songList.length+' · '+songList[songIndex].name);a.onended=()=>{songIndex=(songIndex+1)%songList.length;loadSong();if(!musicMuted)a.play().catch(()=>{})};if(!musicMuted){a.play().then(()=>{musicPlaying=true;updateMusicButtons()}).catch(()=>{musicPlaying=false;updateMusicButtons()})}}function startMusic(){let a=$('#songPlayer');if(!a||!songList.length)return;musicMuted=false;a.volume=musicVolume;a.play().then(()=>{musicPlaying=true;updateMusicButtons()}).catch(()=>{musicPlaying=false;updateMusicButtons()})}function updateMusicButtons(){let b=$('#musicToggle');if(b){b.textContent=musicMuted?'♫×':musicPlaying?'♫':'▶';b.title=musicMuted?'Mostrar música':musicPlaying?'Ocultar música':'Reproducir música'}let s=$('#songStatus');if(s&&songList.length)s.textContent=(songIndex+1)+' / '+songList.length+' · '+songList[songIndex].name}function toggleMusic(){let a=$('#songPlayer');if(!a)return;if(musicMuted||!musicPlaying){musicMuted=false;startMusic()}else{musicMuted=true;a.pause();musicPlaying=false}updateMusicButtons();persistMusic()}function persistMusic(){try{localStorage.setItem('chicago_music_prefs',JSON.stringify({muted:musicMuted,volume:musicVolume}))}catch(e){}}async function initMusic(){let prefs={};try{prefs=JSON.parse(localStorage.getItem('chicago_music_prefs')||'{}')}catch(e){}musicMuted=!!prefs.muted;musicVolume=Number.isFinite(prefs.volume)?prefs.volume:.32;let a=$('#songPlayer');if(a){a.volume=musicVolume;let topVol=$('#topMusicVolume');if(topVol)topVol.value=Math.round(musicVolume*100)}try{if(location.protocol!=='file:'){let r=await fetch('/api/songs',{cache:'no-store'});if(r.ok){let files=await r.json();songList=files.map(name=>({name:name.replace(/\.mp3$/i,''),path:name}))}}}catch(e){}if(!songList.length)songList=(window.CHICAGO_SONGS||[]).map(x=>({name:x.name,path:x.path}));if(songList.length){songIndex=0;loadSong()}else updateMusicButtons();document.addEventListener('pointerdown',()=>{if(!musicMuted&&a&&a.paused&&songList.length)startMusic()},{once:true});updateMusicButtons()}function playSound(type){if(!soundOn)return;try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);o.type='sine';o.frequency.value=type==='goal'?880:440;g.gain.setValueAtTime(.0001,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.08,audioCtx.currentTime+.03);g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+.35);o.start();o.stop(audioCtx.currentTime+.36)}catch(e){}}
